num = 1
top = 0, bottom = size - 1, left = 0, right = size - 1
while num <= size*size:
    // left to right
    for i from left to right:
        matrix[top][i] = num++
    top++
    // top to bottom
    for i from top to bottom:
        matrix[i][right] = num++
    right--
    // right to left (if top <= bottom)
    if top <= bottom:
        for i from right down to left:
            matrix[bottom][i] = num++
        bottom--
    // bottom to top (if left <= right)
    if left <= right:
        for i from bottom down to top:
            matrix[i][left] = num++
        left++
