So we need to guard the `right -= 1` and `bottom -= 1` with checks, or use a different approach.

Better: check boundaries before each direction, and only decrement if we actually did something. Or use the condition `while (top <= bottom && left <= right)` as the outer loop, and inside do the four directions with boundary checks.

Standard spiral matrix algorithm:

```zig
var top = 0;
var bottom = len - 1;
var left = 0;
var right = len - 1;
var num = 1;

while (top <= bottom and left <= right) {
    // left to right
    for (left..right+1) |col| {
        rows[top][col] = @intCast(num);
        num += 1;
    }
    top += 1;

    // top to bottom
    for (top..bottom+1) |row| {
        rows[row][right] = @intCast(num);
        num += 1;
    }
    right -= 1;

    if (top <= bottom) {
        // right to left
        var col = right;
        while (true) {
            rows[bottom][col] = @intCast(num);
            num += 1;
            if (col == left) break;
            col -= 1;
        }
        bottom -= 1;
    }

    if (left <= right) {
        // bottom to top
        var row = bottom;
        while (true) {
            rows[row][left] = @intCast(num);
            num += 1;
            if (row == top) break;
            row -= 1;
        }
        left += 1;
    }
