    if (right > 0) right -= 1; // guard underflow

    if (top <= bottom) {
        // right to left
        var col = right;
        while (true) {
            rows[bottom][col] = @intCast(num);
            num += 1;
            if (col == left) break;
            col -= 1;
        }
        if (bottom > 0) bottom -= 1;
    }

    if (left <= right) {
        // bottom to top
        var row = bottom;
        while (true) {
            rows[row][left] = @intCast(num);
            num += 1;
